 function render(){
  const path=(location.hash.slice(1)||'/').split('?')[0];if(['\/destinations','\/favorites'].includes(previousRoute))collectionPositions.set(collectionReturn,window.scrollY);routeVersion++;if(path!==previousRoute){lastPage=previousRoute||'/';previousRoute=path;}
  $('#modal').close();closeMenu();$('#home').hidden=path!=='/';view.hidden=path==='/';document.body.classList.toggle('inner-page',path!=='/');
  document.querySelectorAll('.header nav a').forEach(a=>{const active=a.getAttribute('href')==='#'+path;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelectorAll('[data-mobile]').forEach(a=>{const active=a.hash==='#'+path||(a.dataset.mobile==='planner'&&['/results','/compare'].includes(path));a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  const [_,base,id,...extra]=path.split('/');
  const validRoute=!extra.length && (['destination','trip','review','book'].includes(base)?Boolean(id):base==='blog'||!id);
  if(path==='/'){ctx.renderCards();ctx.syncHome();document.title=tr('pages.render.1');}
  else if(!validRoute){notFound();document.title=tr('pages.render.2');}
  else if(ctx.routes?.[base]){ctx.routes[base]({view,footer:footer(),bread,heading});document.title=($('#page-view h1')?.textContent||tr('pages.footer.1'))+tr('pages.render.3');}
  else {({destinations:()=>collection(),favorites:()=>collection(true),destination:()=>destination(id),inspiration,planner,results,trip:()=>trip(id),review:()=>review(id),account,compare:comparison,support,privacy:()=>info('privacy'),accessibility:()=>info('accessibility')})[base]?.() ?? (['destinations','favorites','destination','inspiration','blog','planner','results','trip','review','account','compare','support','privacy','accessibility'].includes(base)?undefined:notFound());document.title=($('#page-view h1')?.textContent||tr('pages.footer.1'))+tr('pages.render.3');}
  window.scrollTo({top:collectionPositions.get(location.hash.slice(1))||0,behavior:'instant'});const h=path==='/'?$('#hero-title'):$('#page-view h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}
 }
