 document.addEventListener('change',e=>{if(!e.target.matches('[data-compare]'))return;const id=e.target.dataset.compare;if(e.target.checked&&compare.size>=3){e.target.checked=false;toast(tr('pages.top.8'));return;}if(e.target.checked)compare.add(id);else compare.delete(id);updateCompare();});
 document.addEventListener('brief-changed',()=>{persist();ctx.syncHome();});
 window.addEventListener('hashchange',render);render();
